import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"30 - Upgrade Procedure","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/30-upgrade-procedure.md","filePath":"developers/design-documentation/30-upgrade-procedure.md"}'),n={name:"developers/design-documentation/30-upgrade-procedure.md"};function o(d,e,r,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_30-upgrade-procedure" tabindex="-1">30 - Upgrade Procedure <a class="header-anchor" href="#_30-upgrade-procedure" aria-label="Permalink to &quot;30 - Upgrade Procedure&quot;">​</a></h1><h2 id="supported-update-path" tabindex="-1">Supported Update Path <a class="header-anchor" href="#supported-update-path" aria-label="Permalink to &quot;Supported Update Path&quot;">​</a></h2><p>Use <code>install/update.sh</code> for an existing native/server installation or a local checkout. The script detects the current deployment layout and branch; do not replace it with ad hoc database initialization commands.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/tradeboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install/update.sh</span></span></code></pre></div><p>For Docker deployments, use the update procedure that belongs to the installed Compose layout. Preserve the bind-mounted <code>.env</code> and <code>db/</code> volume.</p><h2 id="what-the-native-script-does" tabindex="-1">What The Native Script Does <a class="header-anchor" href="#what-the-native-script-does" aria-label="Permalink to &quot;What The Native Script Does&quot;">​</a></h2><p><code>install/update.sh</code> performs seven phases:</p><ol><li>Stop the systemd service for a detected server deployment.</li><li>Copy known database files into <code>db/backup_&lt;timestamp&gt;/</code>.</li><li>Stash tracked local modifications and pull the current Git branch.</li><li>Compare <code>.env</code> with <code>.sample.env</code>, preserve existing secrets, and harden older installs.</li><li>Update Python dependencies with <code>uv</code> and ensure Gunicorn/eventlet for server mode.</li><li>Fix server permissions and run <code>upgrade/migrate_all.py</code>.</li><li>Restart systemd/nginx, or finish local development setup.</li></ol><p>The migration runner executes an ordered, idempotent list of targeted scripts. Database modules also use idempotent table initialization during application startup. Tradeboard does not expose a <code>database.init_all_databases()</code> helper.</p><h2 id="backup-requirements" tabindex="-1">Backup Requirements <a class="header-anchor" href="#backup-requirements" aria-label="Permalink to &quot;Backup Requirements&quot;">​</a></h2><p>Before an upgrade, back up <code>.env</code>, signing keys, strategy files, and all six configured stores:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db/tradeboard.db</span></span>
<span class="line"><span>db/logs.db</span></span>
<span class="line"><span>db/latency.db</span></span>
<span class="line"><span>db/health.db</span></span>
<span class="line"><span>db/sandbox.db</span></span>
<span class="line"><span>db/historify.duckdb</span></span></code></pre></div><p>The current updater&#39;s automatic loop copies <code>tradeboard.db</code>, <code>logs.db</code>, <code>latency.db</code>, <code>sandbox.db</code>, and <code>historify.duckdb</code>; it does not include <code>health.db</code>. Copy <code>health.db</code> separately when retaining health history matters. This limitation should remain explicit until the updater is changed.</p><h2 id="environment-review" tabindex="-1">Environment Review <a class="header-anchor" href="#environment-review" aria-label="Permalink to &quot;Environment Review&quot;">​</a></h2><p>The updater keeps an existing <code>.env</code> and reports names that are present in <code>.sample.env</code> but missing locally. Review those values after every upgrade. Never replace production <code>APP_KEY</code>, <code>API_KEY_PEPPER</code>, <code>FERNET_SALT</code>, OAuth signing keys, or broker credentials with sample placeholders.</p><p>If no <code>.env</code> exists, the script creates one from <code>.sample.env</code> and generates fresh <code>APP_KEY</code> and <code>API_KEY_PEPPER</code> values. That is recovery behavior, not a way to rotate secrets on an existing installation.</p><h2 id="frontend-build" tabindex="-1">Frontend Build <a class="header-anchor" href="#frontend-build" aria-label="Permalink to &quot;Frontend Build&quot;">​</a></h2><p>Local mode builds the React bundle only when <code>frontend/dist</code> is absent and npm is available. Server operators should verify the bundle after frontend changes and build explicitly when needed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Then restart the application service.</p><h2 id="migration-runner" tabindex="-1">Migration Runner <a class="header-anchor" href="#migration-runner" aria-label="Permalink to &quot;Migration Runner&quot;">​</a></h2><p>Run the migration set directly only when diagnosing or completing an interrupted update. The equivalent documented invocation from the <code>upgrade</code> directory is <code>cd upgrade &amp;&amp; uv run migrate_all.py</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/migrate_all.py</span></span></code></pre></div><p>The runner preserves warnings for legacy best-effort migrations, but required migrations make its final process exit non-zero. <code>migrate_strategy_module.py</code> is required when this version ships Strategy RMS schema changes; it creates the six <code>sm_</code> tables and adds compatible missing columns/indexes without overwriting historical rows. Require a zero exit code before starting the upgraded application.</p><p><code>upgrade/rotate_pepper.py</code> is deliberately excluded from automatic migration because rotating <code>API_KEY_PEPPER</code> has authentication and ciphertext consequences. It is an explicit operator action.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After updating:</p><ol><li>Confirm the systemd/container process is healthy.</li><li>Open <code>/auth/app-info</code> and verify the expected application version.</li><li>Sign in, reconnect the broker if needed, and confirm master-contract readiness.</li><li>Exercise a read-only API call and a WebSocket authentication/subscription in the intended mode.</li><li>Review <code>log/errors.jsonl</code>, service logs, and migration output.</li><li>Confirm the React bundle loads without stale-chunk errors.</li></ol><p>Swagger UI is disabled; <code>/api/docs</code> is not a verification endpoint. Use the <a href="./../../api-documentation/v1/README.html">API documentation</a> for maintained request contracts.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Stop the service, restore the exact pre-upgrade Git revision and the matching backup files, restore <code>.env</code>/keys if they changed, reinstall dependencies for that revision, and restart. Do not restore one database selectively when a migration changed related state across stores.</p><p>Local changes stashed by the updater are not restored automatically. Review <code>git stash list</code> and apply them deliberately after the upgraded tree is stable.</p>`,32)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
